const file=path.join(base,'protocol.json'),p=JSON.parse(fs.readFileSync(file));fs.copyFileSync(file,path.join(base,'protocol.before-final-freeze.json'));
for(const f of ['src','bin','skills','public','package.json'])fs.cpSync(path.join(source,f),path.join(base,'automatic',f),{recursive:true});
const hash=data=>createHash('sha256').update(data).digest('hex');const fingerprint=root=>hash(JSON.stringify(['package.json',...['src','bin','skills'].flatMap(d=>fs.readdirSync(path.join(root,d),{recursive:true}).filter(f=>fs.statSync(path.join(root,d,f)).isFile()).map(f=>d+'/'+f))].sort().map(f=>[f,hash(fs.readFileSync(path.join(root,f)))])));
p.sourceFingerprints.automatic=fingerprint(path.join(base,'automatic'));p.frozenAt=new Date().toISOString();p.harnessHash=hash(fs.readFileSync('scripts/automatic-model-pilot.mjs'));p.freezeNote='Candidate finalized after regression and compatibility checks, before any model call. Scoring, prompts, order, model and time limits unchanged. Original preparation protocol retained.';
for(const t of p.trials.filter(t=>t.arm==='automatic')){
 if(fs.readdirSync(path.join(t.root,'.dip/events')).length)throw new Error('Fixture not pristine');
 fs.writeFileSync(path.join(t.root,'AGENTS.md'),commonInstructions+'\n');fs.writeFileSync(path.join(t.root,'CLAUDE.md'),'');
 execFileSync(process.execPath,[path.join(base,'automatic/bin/dip.js'),'init','--root',t.root,'--workflow','automatic'],{env:{...process.env,DIP_HOME:path.join(t.dir,'runtime'),DIP_USER_HOME:path.join(base,'user'),DIP_WORKFLOW:'automatic',DIP_GIT_CONFIG:path.join(base,'gi

